// ============================================
// n8n Code Node: 准备图片生成批量请求
// ============================================

// 拿到上一個節點的輸出
const input = $input.first().json;

// 数据在 input.output 里
const data = input.output;

// 安全检查
if (!data || !data.visual_scenes || !Array.isArray(data.visual_scenes)) {
  throw new Error('visual_scenes 不存在或不是数组');
}

console.log(`✅ Found ${data.visual_scenes.length} visual scenes`);

// 获取生物名称 - 尝试多个来源
let creatureName = 'unknown_creature';

try {
  // 尝试1: 从 Google Sheets 节点
  const sheetData = $('Get row(s) in sheet').first().json;
  if (sheetData && sheetData.creature_name) {
    creatureName = sheetData.creature_name;
  }
} catch (e) {
  console.log('⚠️ Cannot get from sheet node');
}

// 尝试2: 从 metadata
if (creatureName === 'unknown_creature' && data.metadata && data.metadata.creature_name) {
  creatureName = data.metadata.creature_name;
}

// 尝试3: 从 video_title 提取
if (creatureName === 'unknown_creature' && data.metadata && data.metadata.video_title) {
  creatureName = data.metadata.video_title.split(':')[0].trim();
}

console.log(`📝 Using creature name: ${creatureName}`);

// 清理和标准化名称
const episodeId = creatureName
  .replace(/[^a-zA-Z0-9\s]/g, '')  // 移除特殊字符
  .trim()
  .replace(/\s+/g, '_')            // 空格变下划线
  .toLowerCase()
  .substring(0, 50);

console.log(`📝 Episode ID: ${episodeId}`);

// 生成批量请求
const batchRequests = data.visual_scenes.map(scene => {
  // 验证必需字段
  if (scene.scene_id === undefined && scene.scene_id !== 0) {
    throw new Error('Scene missing scene_id: ' + JSON.stringify(scene));
  }

  if (!scene.image_prompt) {
    throw new Error(`Scene ${scene.scene_id} missing image_prompt`);
  }

  return {
    channel: "nyxel",
    episode_id: episodeId,
    filename: `scene_${String(scene.scene_id).padStart(2, '0')}.png`,
    prompt: scene.image_prompt,
    model: "gemini-3-pro-image-preview",
    aspect_ratio: "16:9",
    image_size: "2K",
    metadata: {
      scene_anchor: scene.scene_anchor || null,
      used_in_segments: scene.used_in_segments || [],
    }
  };
});

console.log(`✅ Generated ${batchRequests.length} batch requests`);
console.log(`📝 First file: ${batchRequests[0].filename}`);
console.log(`📝 Last file: ${batchRequests[batchRequests.length - 1].filename}`);

return [{
  json: {
    batch_requests: batchRequests,
    summary: {
      total_requests: batchRequests.length,
      creature_name: creatureName,
      episode_id: episodeId,
      file_range: {
        first: batchRequests[0].filename,
        last: batchRequests[batchRequests.length - 1].filename,
      }
    }
  }
}];

// ============================================
// 准备批量音频生成请求
// ============================================

const input = $input.first().json;
const data = input.output;

if (!data || !data.script_segments || !Array.isArray(data.script_segments)) {
  throw new Error('script_segments 不存在');
}

// 获取 episode_id
let sheetRow = $('Get row(s) in sheet').first().json.id;
const episodeId = `ep_${String(sheetRow).padStart(3, '0')}`;

if (data.metadata && data.metadata.file_number) {
  episodeId = data.metadata.file_number.toLowerCase().replace(/[^a-z0-9]/g, '_');
}

console.log(`✅ Processing ${data.script_segments.length} segments`);

// 生成所有 sections
const sections = data.script_segments.map(segment => {
  const cleanText = segment.text_content
    .replace(/\r\n/g, ' ')
    .replace(/\n/g, ' ')
    .replace(/\t/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  return {
    index: segment.index,
    name: `part_${String(segment.index).padStart(3, '0')}`,
    type: "single",
    voice: "Charon",
    prompt: "You are a tired but welcoming archivist sitting in a quiet, rain-soaked library. Speak in a deep, warm chest voice with an intimate but emotionally flat tone. Keep your pacing slow and deliberate, with a gentle downward inflection at the end of each sentence to signal calm and safety. Keep your tone calm and even, avoiding dramatic rises, emotional peaks, or strong emphasis on any word. Minimize pitch variation and stay mostly flat, as if you are quietly documenting neutral facts for a trusted colleague rather than telling a story. Your energy level must stay low, steady, and consistent from the beginning to the end of the audio.",
    text: cleanText
  };
});

console.log(`✅ Generated payload with ${sections.length} sections`);

// 返回单个 item，包含所有 sections
return [{
  json: {
    channel: "nyxel",
    episode_id: episodeId,
    sections: sections
  }
}];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const item = JSON.parse($input.first().json.content.parts[0].text)

return item;

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const item = JSON.stringify($input.first().json.content.parts[0].text)

return item

// 獲取原始文本
const rawText = $input.first().json.content.parts[0].text;

// 解析 JSON (如果有 Markdown ```json 包裹，最好先清洗一下，這裡假設是純 JSON)
// 如果你的模型輸出帶有 ```json，請使用: const cleanText = rawText.replace(/```json|```/g, '');
const segments = JSON.parse(rawText);

// 關鍵修改：不要直接 return segments
// 把它包在一個屬性裡，這樣 n8n 就只會把它當作 1 個 Item
return {
  json: {
    full_blueprint: segments 
  }
};

