// ============================================
// 准备批量音频生成请求 (已修正数据映射)
// ============================================

const input = $input.first().json;
const data = input.output;

// 1. 修正验证逻辑：匹配实际的输入字段 'narrative_log'
if (!data || !data.narrative_log || !Array.isArray(data.narrative_log)) {
  throw new Error(`narrative_log 不存在或格式错误。当前 data keys: ${Object.keys(data || {}).join(', ')}`);
}

// 获取 episode_id
// 注意：如果前面的 'Get row(s) in sheet' 节点没有运行，这里会报错。
let sheetRow = 0;
try {
    sheetRow = $('Get row(s) in sheet').first().json.id;
} catch (e) {
    console.log('未找到 sheet row id，使用默认值 0');
}

// 2. 修正：使用 let 而不是 const，因为后面有重新赋值的逻辑
let episodeId = `ep_${String(sheetRow).padStart(3, '0')}`;

if (data.metadata && data.metadata.file_number) {
  episodeId = data.metadata.file_number.toLowerCase().replace(/[^a-z0-9]/g, '_');
}

console.log(`✅ Processing ${data.narrative_log.length} segments`);

// 生成所有 sections
// 3. 修正：遍历 'narrative_log'
const sections = data.narrative_log.map(segment => {
  // 4. 修正：获取 'content' 而不是 'text_content'
  const rawText = segment.content || ""; 

  const cleanText = rawText
    .replace(/\r\n/g, ' ')
    .replace(/\n/g, ' ')
    .replace(/\t/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  return {
    // 5. 修正：使用 'id' 映射 index
    index: segment.id,
    name: `part_${String(segment.id).padStart(3, '0')}`,
    type: "single",
    voice: "Charon",
    prompt: "Generate audio in the style of a weary British academic recording a voice log late at night.CORE STYLE: RESTRAINED & UNDERSTATED Narrow Pitch Range: Do not use a wide range of high and low notes. Keep the voice operating in a tight, low-mid range. It shouldn't be a robot, but it shouldn't be a roller coaster.Delivery: Matter-of-fact and resigned. Read the text as if these are simple, undeniable facts. Avoid dramatic pauses or theatrical emphasis.Vibe: Professional but tired. There is a slight melody to the voice (so it's not robotic), but it is a melancholic, downward-inflecting melody.Texture: Clear, deep, and smooth. Not whispering, but speaking with low energy.",
    text: cleanText
  };
});

console.log(`✅ Generated payload with ${sections.length} sections`);

// 返回单个 item，包含所有 sections
return [{
  json: {
    channel: "nyxel",
    episode_id: episodeId,
    sections: sections
  }
}];

